void ssd1306_fb_clear(uint8_t*f,size_t n){if(f)memset(f,0,n);}
void ssd1306_fb_pixel(uint8_t*f,uint8_t x,uint8_t y,bool on){if(!f||x>=128||y>=64)return;uint16_t i=(uint16_t)(y>>3)*128+x;uint8_t m=(uint8_t)(1U<<(y&7));if(on)f[i]|=m;else f[i]&=(uint8_t)~m;}
void ssd1306_fb_char(uint8_t*f,uint8_t x,uint8_t page,char c){if(!f||page>=8||x>=128)return;unsigned g=(c>=0x20&&c<=0x7e)?(unsigned)c-0x20:0;for(unsigned col=0;col<5&&x+col<128;col++)f[(uint16_t)page*128+x+col]=s_font[g][col];if(x+5<128)f[(uint16_t)page*128+x+5]=0;}
void ssd1306_fb_text(uint8_t*f,uint8_t x,uint8_t page,const char*t){while(f&&t&&*t&&x+5<128){ssd1306_fb_char(f,x,page,*t++);x=(uint8_t)(x+6);}}
void ssd1306_fb_progress(uint8_t*f,uint8_t x,uint8_t page,uint8_t width,uint8_t percent){if(!f||page>=8||width<3||x+width>128)return;if(percent>100)percent=100;for(uint8_t i=0;i<width;i++){uint8_t v=(i==0||i==width-1)?0x7f:0x41;if(i>1&&i<width-1&&((uint16_t)(i-1)*100U/(width-2))<percent)v=0x7f;f[(uint16_t)page*128+x+i]=v;}}
